import { Button, Group, PasswordInput, Stack } from '@mantine/core';
import { matchesField, useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { PasswordInputWithStrength } from './PasswordInputWithStrength';
import { validatePassword } from './requirements';

interface PasswordValues {
  password: string;
  confirmPassword: string;
}

function updatePassword(values: PasswordValues) {
  return new Promise<PasswordValues>((resolve) => {
    setTimeout(() => resolve(values), 1000);
  });
}

export function PasswordStrength() {
  const form = useForm<PasswordValues>({
    mode: 'uncontrolled',
    initialValues: { password: '', confirmPassword: '' },
    validate: {
      password: validatePassword,
      confirmPassword: matchesField('password', 'Passwords do not match'),
    },
  });

  const handleSubmit = async (values: PasswordValues) => {
    await updatePassword(values);
    notifications.show({
      title: 'Password updated',
      message: 'Use your new password the next time you sign in',
    });
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit)}>
      <Stack>
        <PasswordInputWithStrength
          label="New password"
          placeholder="Your new password"
          withAsterisk
          {...form.getInputProps('password')}
        />
        <PasswordInput
          label="Confirm password"
          placeholder="Repeat your new password"
          withAsterisk
          {...form.getInputProps('confirmPassword')}
        />
        <Group justify="flex-end">
          <Button type="submit" loading={form.submitting}>
            Update password
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { useState } from 'react';
import { CheckIcon, XIcon } from '@phosphor-icons/react';
import { Group, PasswordInput, Popover, Progress, Stack, Text } from '@mantine/core';
import { useUncontrolled } from '@mantine/hooks';
import { getStrength, getStrengthColor, PASSWORD_REQUIREMENTS } from './requirements';

interface PasswordInputWithStrengthProps {
  label?: React.ReactNode;
  placeholder?: string;
  withAsterisk?: boolean;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  onFocus?: (event: React.FocusEvent<HTMLInputElement>) => void;
  onBlur?: (event: React.FocusEvent<HTMLInputElement>) => void;
  error?: React.ReactNode;
}

export function PasswordInputWithStrength({
  label,
  placeholder,
  withAsterisk,
  value,
  defaultValue,
  onChange,
  onFocus,
  onBlur,
  error,
}: PasswordInputWithStrengthProps) {
  const [opened, setOpened] = useState(false);

  // onChange is passed as is so that the component subscribes to the form field
  const [password, handleChange] = useUncontrolled({
    value,
    defaultValue,
    finalValue: '',
    onChange,
  });

  const strength = getStrength(password);

  const checks = PASSWORD_REQUIREMENTS.map((requirement) => {
    const passed = requirement.re.test(password);
    return (
      <Group key={requirement.label} gap="xs">
        {passed ? (
          <CheckIcon size={14} weight="bold" color="var(--mantine-color-teal-6)" />
        ) : (
          <XIcon size={14} weight="bold" color="var(--mantine-color-red-6)" />
        )}
        <Text size="sm" c={passed ? 'teal' : 'red'}>
          {requirement.label}
        </Text>
      </Group>
    );
  });

  return (
    <Popover opened={opened} position="bottom-start" width="target">
      <Popover.Target>
        <PasswordInput
          label={label}
          placeholder={placeholder}
          withAsterisk={withAsterisk}
          value={password}
          error={error}
          onChange={(event) => handleChange(event.currentTarget.value)}
          onFocus={(event) => {
            setOpened(true);
            onFocus?.(event);
          }}
          onBlur={(event) => {
            setOpened(false);
            onBlur?.(event);
          }}
        />
      </Popover.Target>
      <Popover.Dropdown>
        <Stack gap="xs">
          <Progress value={strength} color={getStrengthColor(strength)} size="sm" />
          <Stack gap={6}>{checks}</Stack>
        </Stack>
      </Popover.Dropdown>
    </Popover>
  );
}

export interface PasswordRequirement {
  re: RegExp;
  label: string;
}

export const PASSWORD_REQUIREMENTS: PasswordRequirement[] = [
  { re: /.{8,}/, label: 'At least 8 characters' },
  { re: /[0-9]/, label: 'Includes a number' },
  { re: /[a-z]/, label: 'Includes a lowercase letter' },
  { re: /[A-Z]/, label: 'Includes an uppercase letter' },
  { re: /[$&+,:;=?@#|'<>.^*()%!-]/, label: 'Includes a special symbol' },
];

export function getStrength(password: string) {
  const passed = PASSWORD_REQUIREMENTS.filter((requirement) => requirement.re.test(password));
  return Math.round((passed.length / PASSWORD_REQUIREMENTS.length) * 100);
}

export function getStrengthColor(strength: number) {
  if (strength === 100) {
    return 'teal';
  }

  return strength >= 60 ? 'yellow' : 'red';
}

export function validatePassword(password: string) {
  const failed = PASSWORD_REQUIREMENTS.find((requirement) => !requirement.re.test(password));
  return failed ? `Password must satisfy: ${failed.label.toLowerCase()}` : null;
}
